package me.minis.ledger;
import android.database.*;import android.database.sqlite.*;import android.content.*;import org.json.*;import java.util.*;
/** User operations only; before/after snapshots and the edit commit in the same transaction. */
public final class UndoLog {
 static void install(SQLiteDatabase db){
  db.execSQL("CREATE TABLE IF NOT EXISTS edit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,label TEXT NOT NULL,time INTEGER NOT NULL,undone INTEGER NOT NULL DEFAULT 0)");
  db.execSQL("CREATE TABLE IF NOT EXISTS edit_context(id INTEGER NOT NULL)");if(DatabaseUtils.longForQuery(db,"SELECT count(*) FROM edit_context",null)==0)db.execSQL("INSERT INTO edit_context VALUES(0)");
  db.execSQL("CREATE TABLE IF NOT EXISTS edit_before AS SELECT e.*,CAST(0 AS INTEGER) AS op FROM entries e WHERE 0");db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS edit_before_key ON edit_before(op,_id)");
  db.execSQL("CREATE TABLE IF NOT EXISTS edit_after AS SELECT e.*,CAST(0 AS INTEGER) AS op FROM entries e WHERE 0");db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS edit_after_key ON edit_after(op,_id)");
  for(String t:new String[]{"edit_bu","edit_au","edit_ai"})db.execSQL("DROP TRIGGER IF EXISTS "+t);
  db.execSQL("CREATE TRIGGER edit_bu BEFORE UPDATE ON entries WHEN (SELECT id FROM edit_context)>0 BEGIN INSERT OR IGNORE INTO edit_before SELECT e.*,(SELECT id FROM edit_context) FROM entries e WHERE e._id=old._id AND NOT EXISTS(SELECT 1 FROM edit_after WHERE _id=old._id AND op=(SELECT id FROM edit_context)); END");
  String cols="",vals="";try(Cursor c=db.rawQuery("PRAGMA table_info(entries)",null)){while(c.moveToNext()){String n=c.getString(1);cols+=(cols.isEmpty()?"":",")+n;vals+=(vals.isEmpty()?"":",")+"new."+n;}}
  for(String event:new String[]{"UPDATE","INSERT"})db.execSQL("CREATE TRIGGER "+(event.equals("UPDATE")?"edit_au":"edit_ai")+" AFTER "+event+" ON entries WHEN (SELECT id FROM edit_context)>0 BEGIN INSERT OR REPLACE INTO edit_after ("+cols+",op) VALUES("+vals+",(SELECT id FROM edit_context)); END");
 }
 public interface Action{Object run()throws Exception;}
 static Object record(LedgerDb helper,String label,Action action)throws Exception{SQLiteDatabase db=helper.getWritableDatabase();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("label",label);v.put("time",System.currentTimeMillis());long id=db.insertOrThrow("edit_log",null,v);db.execSQL("UPDATE edit_context SET id=?",new Object[]{id});Object result=action.run();db.execSQL("UPDATE edit_context SET id=0");if(DatabaseUtils.longForQuery(db,"SELECT (SELECT count(*) FROM edit_after WHERE op=?)+(SELECT count(*) FROM finance_after WHERE op=?)",new String[]{""+id,""+id})==0)db.delete("edit_log","id=?",new String[]{""+id});trim(db);db.setTransactionSuccessful();return result;}finally{db.endTransaction();helper.notifyChanged();}}
 static void trim(SQLiteDatabase db){db.execSQL("DELETE FROM edit_log WHERE id NOT IN (SELECT id FROM edit_log ORDER BY id DESC LIMIT 100)");for(String t:new String[]{"edit_before","edit_after","finance_before","finance_after"})db.execSQL("DELETE FROM "+t+" WHERE op NOT IN (SELECT id FROM edit_log)");}
 static JSONObject row(Cursor c)throws JSONException{JSONObject o=new JSONObject();for(int i=0;i<c.getColumnCount();i++){String n=c.getColumnName(i);if(n.equals("op"))continue;switch(c.getType(i)){case Cursor.FIELD_TYPE_INTEGER:o.put(n,c.getLong(i));break;case Cursor.FIELD_TYPE_NULL:o.put(n,JSONObject.NULL);break;default:o.put(n,c.getString(i));}}return o;}
 static JSONObject get(SQLiteDatabase db,String table,long id,long op)throws JSONException{try(Cursor c=db.rawQuery("SELECT * FROM "+table+" WHERE _id=?"+(op>0?" AND op=?":""),op>0?new String[]{""+id,""+op}:new String[]{""+id})){return c.moveToFirst()?row(c):null;}}
 static boolean equal(JSONObject a,JSONObject b)throws JSONException{if(a==null||b==null)return a==b;if(a.length()!=b.length())return false;Iterator<String> k=a.keys();while(k.hasNext()){String n=k.next();if(!a.get(n).toString().equals(b.opt(n)==null?"":b.get(n).toString()))return false;}return true;}
 static JSONArray list(SQLiteDatabase db,long entry)throws JSONException{JSONArray out=new JSONArray();String where=entry>0?" WHERE id IN (SELECT op FROM edit_after WHERE _id=? UNION SELECT op FROM finance_after WHERE entry=? OR peer=?)":"";try(Cursor c=db.rawQuery("SELECT id,label,time,undone FROM edit_log"+where+" ORDER BY id DESC LIMIT 100",entry>0?new String[]{""+entry,""+entry,""+entry}:null)){while(c.moveToNext()){long id=c.getLong(0);JSONObject o=new JSONObject().put("id",id).put("label",c.getString(1)).put("time",c.getLong(2)).put("undone",c.getInt(3)).put("count",DatabaseUtils.longForQuery(db,"SELECT (SELECT count(*) FROM edit_after WHERE op=?)+(SELECT count(*) FROM finance_after WHERE op=?)",new String[]{""+id,""+id}));if(entry>0){JSONObject before=get(db,"edit_before",entry,id),after=get(db,"edit_after",entry,id);o.put("before",before==null?JSONObject.NULL:visible(before)).put("after",after==null?JSONObject.NULL:visible(after));}out.put(o);}}return out;}
 static JSONObject visible(JSONObject o)throws JSONException{JSONObject v=new JSONObject();for(String k:new String[]{"time","kind","cents","merchant","category","status","excluded"})v.put(k,o.opt(k));return v;}
 static int undo(LedgerDb helper,long op)throws Exception{SQLiteDatabase db=helper.getWritableDatabase();int count=0;db.beginTransaction();try{if(DatabaseUtils.longForQuery(db,"SELECT count(*) FROM edit_log WHERE id=? AND undone=0",new String[]{""+op})!=1)throw new IllegalStateException("该操作已撤销或记录不存在");FinanceBackup.undoObjects(db,op);try(Cursor c=db.rawQuery("SELECT _id FROM edit_after WHERE op=?",new String[]{""+op})){while(c.moveToNext()){long id=c.getLong(0);JSONObject after=get(db,"edit_after",id,op),current=get(db,"entries",id,0);if(!equal(after,current))throw new IllegalStateException("相关账目后来发生了变化，不能直接撤销；本次未修改");JSONObject before=get(db,"edit_before",id,op);if(before==null)db.delete("entries","_id=?",new String[]{""+id});else{ContentValues v=new ContentValues();Iterator<String> keys=before.keys();while(keys.hasNext()){String k=keys.next();if(k.equals("_id"))continue;Object x=before.get(k);if(x==JSONObject.NULL)v.putNull(k);else if(x instanceof Number)v.put(k,((Number)x).longValue());else v.put(k,x.toString());}db.update("entries",v,"_id=?",new String[]{""+id});}count++;}}
  FinanceBackup.restoreUndoObjects(db,op);FinanceData.validateAll(db);db.execSQL("UPDATE edit_log SET undone=1 WHERE id=?",new Object[]{op});db.setTransactionSuccessful();return count;
 }finally{db.endTransaction();helper.notifyChanged();}}
 static void clear(SQLiteDatabase db){db.delete("finance_before",null,null);db.delete("finance_after",null,null);db.delete("edit_before",null,null);db.delete("edit_after",null,null);db.delete("edit_log",null,null);}
}
